mapper.select:
SELECT count(*)
FROM relation re
         LEFT JOIN work w ON re.work_id = w.id
         LEFT JOIN work_user wu ON w.id = wu.work_id
WHERE wu.user_id = #{userId}
  AND re.company_id = #{companyId};

SELECT *
FROM relation r
         LEFT JOIN `work` w ON r.work_id = w.id

    w.del_flag != 1

        AND r.company_id = #{companyId}


        AND w.salary = #{salary}


        AND w.education = #{education}


        AND w.job_experience = #{jobExperience}


        AND w.classify_id = #{classifyId}

SELECT wu.*
FROM relation re
         LEFT JOIN work w ON re.work_id = w.id
         LEFT JOIN work_user wu ON w.id = wu.work_id
WHERE wu.user_id = #{userId}
  AND re.company_id = #{companyId}
  AND wu.resume_id = #{resumeId}
